def safety_mode(apps, schema_editor):
    apps.get_model('training', 'TrainingSession').objects.filter(
        scenario__boundary_type='SAFETY'
    ).update(feedback_mode='combined')
    # Preserve historical action plans in the independent notes editor.
    for note in apps.get_model('training', 'Reflection').objects.exclude(action_plan='').iterator():
        if note.action_plan not in note.reflection_text:
            note.reflection_text = note.reflection_text + '\n\n' + note.action_plan
            note.save(update_fields=['reflection_text'])


